-- Revert game rules to previous versions (from seeds 000015 and 000028)

UPDATE games SET rules = E'# Дилемма заключённого (Prisoner''s Dilemma)\n\n## Описание\n\nКлассическая игра из теории игр, в которой два игрока одновременно выбирают одно из двух действий: **сотрудничать** или **предать**.\n\n## Правила\n\n### Ходы\nКаждый раунд оба игрока одновременно делают выбор:\n- `C` (Cooperate) - сотрудничать\n- `D` (Defect) - предать\n\n### Подсчёт очков\n\n| Игрок 1 | Игрок 2 | Очки игрока 1 | Очки игрока 2 |\n|---------|---------|---------------|---------------|\n| C       | C       | 3             | 3             |\n| C       | D       | 0             | 5             |\n| D       | C       | 5             | 0             |\n| D       | D       | 1             | 1             |\n\n## Протокол взаимодействия\n\n### Ввод\nКаждый ход: предыдущий ход противника (`C` или `D`), или пустая строка для первого хода\n\n### Вывод\nНа каждый ход выведите ваш выбор: `C` или `D`',
updated_at = NOW()
WHERE name = 'prisoners_dilemma';

UPDATE games SET rules = E'# Перетягивание каната (Tug of War)\n\n## Описание\n\nИгра на управление ресурсами, в которой два игрока соревнуются в перетягивании каната, расходуя энергию.\n\n## Правила\n\n### Начальные условия\n- Канат находится в позиции **0** (центр)\n- Каждый игрок имеет **100 единиц энергии**\n- Цель: переместить канат на свою сторону\n\n### Механика\n- Каждый раунд игроки одновременно выбирают, сколько энергии потратить (от 0 до доступного количества)\n- Канат смещается в сторону игрока, потратившего больше энергии\n- Величина смещения = разница потраченной энергии\n\n### Победа\n- Игрок 1 побеждает, если канат в позиции >= 10\n- Игрок 2 побеждает, если канат в позиции <= -10\n- Игра заканчивается после **50 раундов** или при достижении победной позиции\n\n## Протокол взаимодействия\n\n### Ввод\n```\n<позиция_каната> <ваша_энергия> <энергия_противника> <ход_противника>\n```\n\nДля первого хода `<ход_противника>` будет -1.\n\n### Вывод\nНа каждый ход выведите число от 0 до вашей текущей энергии.',
updated_at = NOW()
WHERE name = 'tug_of_war';

UPDATE games SET rules = E'# Дилемма путешественника (Traveler''s Dilemma)\n\n## Описание\n\nДва путешественника потеряли одинаковые чемоданы. Авиакомпания просит каждого независимо назвать стоимость в диапазоне от **L** до **U** (по умолчанию от 2 до 100).\n\n## Правила\n\n### Подсчёт очков\n\n- Если оба назвали **одинаковое** число — оба получают это число\n- Если числа **различаются**:\n  - Оба получают **меньшее** из двух чисел\n  - Назвавший меньше получает бонус **+R** (по умолчанию R=2)\n  - Назвавший больше получает штраф **-R**\n\n### Пример\n\n| Игрок 1 | Игрок 2 | Очки игрока 1 | Очки игрока 2 |\n|---------|---------|---------------|---------------|\n| 50      | 50      | 50            | 50            |\n| 30      | 70      | 32 (30+R)     | 28 (30-R)     |\n| 80      | 40      | 38 (40-R)     | 42 (40+R)     |\n| 2       | 2       | 2             | 2             |\n\n### Дилемма\n\nРавновесие Нэша — оба называют минимум (L=2), но на практике кооперативные стратегии (~90) часто побеждают.\n\n## Протокол взаимодействия\n\n### Инициализация\nПрограмма получает 4 строки:\n```\n2       <- нижняя граница (L)\n100     <- верхняя граница (U)\n2       <- бонус/штраф (R)\n100     <- количество итераций\n```\n\n### Каждая итерация\n\n**Вывод:** целое число в диапазоне [L, U] — ваша заявка\n\n**Ввод:** заявка противника (целое число)\n\n### Ограничения\n- Заявка должна быть в диапазоне [L, U], иначе программа получит ошибку',
updated_at = NOW()
WHERE name = 'travelers_dilemma';

UPDATE games SET rules = E'# Общественное благо (Public Goods Game)\n\n## Описание\n\nУ каждого игрока в начале каждой итерации есть **E** токенов (по умолчанию E=20). Оба одновременно выбирают, сколько вложить в общий пул. Пул умножается на множитель **m** (по умолчанию m=1.5) и делится поровну.\n\n## Правила\n\n### Формула выплаты\n\n```\nВыплата = (E - ваш_вклад) + m × (вклад_1 + вклад_2) / 2\n```\n\nРезультат усекается до целого числа.\n\n### Примеры\n\n| Вклад 1 | Вклад 2 | Очки 1 | Очки 2 | Комментарий |\n|---------|---------|--------|--------|-------------|\n| 20      | 20      | 30     | 30     | Оба вложили всё: 0 + 1.5×40/2 = 30 |\n| 0       | 0       | 20     | 20     | Никто не вложил: 20 + 0 = 20 |\n| 0       | 20      | 35     | 15     | Безбилетник: 20+15=35, щедрый: 0+15=15 |\n| 10      | 10      | 25     | 25     | Частичный вклад: 10 + 1.5×20/2 = 25 |\n\n### Дилемма\n\n- Если оба вложат всё (E=20): каждый получает **m×E = 30**. Отлично!\n- Если один вложит всё, другой 0: щедрый получает **15**, жадный — **35**\n- Равновесие Нэша: не вкладывать ничего (каждый получает **20**) — хуже, чем сотрудничество\n\n## Протокол взаимодействия\n\n### Инициализация\nПрограмма получает 3 строки:\n```\n20      <- начальный капитал (E)\n1.5     <- множитель (m), дробное число\n100     <- количество итераций\n```\n\n### Каждая итерация\n\n**Вывод:** целое число в диапазоне [0, E] — ваш вклад в общий пул\n\n**Ввод:** вклад противника (целое число)\n\n### Ограничения\n- Вклад не может превышать E, иначе программа получит ошибку',
updated_at = NOW()
WHERE name = 'public_goods';

UPDATE games SET rules = E'# Аукцион двойной цены (Dollar Auction)\n\n## Описание\n\nНа торги выставляется приз стоимостью **P** (по умолчанию P=100). Игроки **поочерёдно** делают ставки. Ключевое правило: **оба** платят свои последние ставки, но приз получает только победитель.\n\n## Правила\n\n### Механика торгов\n\n1. Игроки ходят **по очереди** (первый игрок начинает)\n2. Каждая ставка должна быть **строго больше** последней ставки противника\n3. Можно **спасовать** (ставка = 0) — торги заканчиваются\n4. Торги также заканчиваются при достижении лимита раундов\n\n### Подсчёт очков\n\n- **Победитель** (чья ставка выше): получает `приз - своя_ставка`\n- **Проигравший**: теряет `своя_ставка` (получает `-своя_ставка`)\n- Если оба спасовали: оба получают **0**\n\n### Примеры\n\n| Ход | Игрок 1 | Игрок 2 | Результат |\n|-----|---------|---------|----------|\n| 1→ пас | 0 | — | Оба: 0, 0 |\n| 1→1, 2→ пас | 1 | 0 | П1 выигрывает: 99, 0 |\n| 1→1, 2→2, 1→3, 2→ пас | 3 | 2 | П1: 97, П2: -2 |\n| 1→50, 2→60, 1→70, 2→ пас | 70 | 60 | П1: 30, П2: -60 |\n| 1→80, 2→90, 1→110, 2→ пас | 110 | 90 | П1: -10, П2: -90 |\n\n### Ловушка эскалации (Sunk Cost)\n\nКогда игрок уже вложил значительную сумму, ему «выгоднее» повысить ставку, чем потерять вложенное. Но противник рассуждает аналогично — спираль может привести к ставкам, **превышающим приз**!\n\n## Протокол взаимодействия\n\n### Инициализация\nПрограмма получает 2 строки:\n```\n100     <- стоимость приза (P)\n100     <- максимальное количество раундов\n```\n\n### Каждый ход\n\n**Ввод:** последняя ставка противника (целое число, 0 если торги только начались)\n\n**Вывод:** ваша ставка — целое число, строго больше ставки противника, или 0 чтобы спасовать\n\n### Ограничения\n- Ставка должна быть ≥ 0\n- Если ставка > 0, она должна быть строго больше последней ставки противника\n- Нарушение → ошибка программы\n\n### ⚠️ Особенность\nЭто **поочерёдная** игра (в отличие от остальных игр, где ходы делаются одновременно). Первый игрок всегда ходит первым в каждом раунде торгов.',
updated_at = NOW()
WHERE name = 'dollar_auction';
